import { useEffect } from 'react';
import { AppHypercubeImageNavigator } from '../../lib/AppHypercubeImageNavigator';
import style from './styles.module.css';

const HypercubeImageNavigation = () => {

	const id = 'imageApp'
	const url = process.env.PUBLIC_URL + '/static/hypercube/img/a.jpg'

	useEffect(()=>{
		new AppHypercubeImageNavigator(id, url)
	},[])

	return (
		<div className={style.hypercubeEnv}>
			<div className={style.hypercubeDivWrapper}>
				<div className={style.hypercubeDiv} id={id} style={{ height: '100%', 
					backgroundColor: 'black' 
					}}>
				</div>
			</div>
		</div>
	);
};

export default HypercubeImageNavigation;
