import { useEffect, useRef, useState } from 'react';

export interface MediaItem {
	type: 'image' | 'video' | 'gif';
	src: string;
	duration?: number;
	text?: string;
}

interface MediaSliderProps {
	mediaList?: MediaItem[];
	mediaListButton?: MediaItem[];
}

const MediaSlider: React.FC<MediaSliderProps> = ({ mediaList = [], mediaListButton = [] }) => {
	const [currentIndex, setCurrentIndex] = useState(0);
	const [fade, setFade] = useState(true);
	const [activeList, setActiveList] = useState<MediaItem[]>(mediaList);
	const [isTempListPlaying, setIsTempListPlaying] = useState(false);
	const [textVisible, setTextVisible] = useState<string | null>(null);
	const [isFullscreen, setIsFullscreen] = useState(false);

	const videoRef = useRef<HTMLVideoElement>(null);
	const sliderRef = useRef<HTMLDivElement>(null);
	const timerRef = useRef<NodeJS.Timeout | null>(null);
	const textTimerRef = useRef<NodeJS.Timeout | null>(null);

	const currentMedia = activeList[currentIndex];

	const clearTimer = () => {
		if (timerRef.current) {
			clearTimeout(timerRef.current);
			timerRef.current = null;
		}
		if (textTimerRef.current) {
			clearTimeout(textTimerRef.current);
			textTimerRef.current = null;
		}
	};

	useEffect(() => {
		if (textTimerRef.current) clearTimeout(textTimerRef.current);
		if (currentMedia.text) {
			setTextVisible(currentMedia.text);
			textTimerRef.current = setTimeout(() => setTextVisible(null), 1500);
		} else {
			setTextVisible(null);
		}

		return () => {
			if (textTimerRef.current) clearTimeout(textTimerRef.current);
		};
	}, [currentIndex, currentMedia]);

	useEffect(() => {
		clearTimer();
		if (currentMedia.type === 'image' || currentMedia.type === 'gif') {
			const dur = currentMedia.duration ?? 3000;
			timerRef.current = setTimeout(() => handleNext(), dur);
		}
		return () => clearTimer();
	}, [currentIndex, currentMedia]);

	useEffect(() => {
		if (currentMedia.type === 'video' && videoRef.current) {
			videoRef.current.currentTime = 0;
			videoRef.current.play().catch((err) => console.error('fail to play:', err));
		}
	}, [currentIndex, currentMedia]);

	useEffect(() => {
		const handleTimeUpdate = () => {
			if (videoRef.current && currentMedia.type === 'video') {
				const timeLeft = videoRef.current.duration - videoRef.current.currentTime;
				if (timeLeft <= 1 && timeLeft > 0) {
					setFade(false);
				}
			}
		};

		const videoElement = videoRef.current;
		if (videoElement && currentMedia.type === 'video') {
			videoElement.addEventListener('timeupdate', handleTimeUpdate);
			return () => videoElement.removeEventListener('timeupdate', handleTimeUpdate);
		}
	}, [currentMedia.type]);

	const startTransition = (newIndex: number) => {
		if (videoRef.current) {
			videoRef.current.pause();
			videoRef.current.currentTime = 0;
		}
		clearTimer();
		setFade(false);
		setTimeout(() => {
			setCurrentIndex(newIndex);
			setFade(true);
		}, 500);
	};

	const handleNext = () => {
		const nextIndex = currentIndex + 1;

		if (isTempListPlaying) {
			if (nextIndex >= activeList.length) {
				setActiveList(mediaList);
				setCurrentIndex(0);
				setIsTempListPlaying(false);
			} else {
				startTransition(nextIndex);
			}
		} else {
			startTransition(nextIndex % activeList.length);
		}
	};

	const handlePrev = () => {
		startTransition((currentIndex - 1 + activeList.length) % activeList.length);
	};

	const handleVideoEnd = () => {
		if (isTempListPlaying) {
			setActiveList(mediaList);
			setCurrentIndex(0);
			setIsTempListPlaying(false);
		} else {
			handleNext();
		}
	};

	const toggleFullScreen = () => {
		if (!document.fullscreenElement) {
			if (sliderRef.current) {
				if (sliderRef.current.requestFullscreen) {
					sliderRef.current.requestFullscreen();
				} else if ((sliderRef.current as any).webkitRequestFullscreen) {
					(sliderRef.current as any).webkitRequestFullscreen();
				} else if ((sliderRef.current as any).msRequestFullscreen) {
					(sliderRef.current as any).msRequestFullscreen();
				}
			}
		} else {
			document.exitFullscreen();
		}
	};

	useEffect(() => {
		const handleFullscreenChange = () => {
			setIsFullscreen(!!document.fullscreenElement);
		};

		document.addEventListener('fullscreenchange', handleFullscreenChange);
		return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
	}, []);

	useEffect(() => {
		const handleKeyDown = (e: KeyboardEvent) => {
			if (e.key === 'Escape' && document.fullscreenElement) {
				document.exitFullscreen();
			}

			const key = parseInt(e.key);
			if (!isNaN(key) && key >= 1 && key <= mediaListButton.length) {
				const selected = mediaListButton[key - 1];
				setActiveList([selected]);
				setCurrentIndex(0);
				setIsTempListPlaying(true);
			}
		};

		window.addEventListener('keydown', handleKeyDown);
		return () => window.removeEventListener('keydown', handleKeyDown);
	}, [mediaListButton]);

	useEffect(() => {
		const handleArrowKey = (e: KeyboardEvent) => {
			if (e.key === 'ArrowRight') {
				handleNext();
			} else if (e.key === 'ArrowLeft') {
				handlePrev();
			}
		};

		window.addEventListener('keydown', handleArrowKey);
		return () => window.removeEventListener('keydown', handleArrowKey);
	}, [currentIndex, activeList]);

	return (
		<div
			ref={sliderRef}
			style={{
				position: 'relative',
				width: '100%',
				height: '100%',
				backgroundColor: '#000',
			}}
		>
			<div
				style={{
					position: 'absolute',
					width: '100%',
					height: '100%',
					top: 0,
					left: 0,
					overflow: 'hidden',
				}}
			>
				{currentMedia.type === 'image' || currentMedia.type === 'gif' ? (
					<img
						src={currentMedia.src}
						alt="media"
						style={{
							width: '100%',
							height: '100%',
							objectFit: 'cover',
							opacity: fade ? 1 : 0,
							transition: 'opacity 0.5s ease-in-out',
						}}
					/>
				) : (
					<video
						ref={videoRef}
						src={currentMedia.src}
						muted
						playsInline
						onEnded={handleVideoEnd}
						style={{
							width: '100%',
							height: '100%',
							objectFit: 'cover',
							opacity: fade ? 1 : 0,
							transition: 'opacity 0.5s ease-in-out',
						}}
					/>
				)}

				{textVisible && (
					<div
						style={{
							position: 'absolute',
							top: '50%',
							left: '50%',
							transform: 'translate(-50%, -50%)',
							color: 'white',
							fontSize: '68px',
							fontWeight: 'bold',
							textShadow: '0 0 8px rgba(0,0,0,0.7)',
							pointerEvents: 'none',
						}}
					>
						{textVisible}
					</div>
				)}
			</div>

			<button
				onClick={handlePrev}
				style={{
					position: 'absolute',
					top: '50%',
					left: '10px',
					transform: 'translateY(-50%)',
					padding: '10px',
					backgroundColor: 'rgba(0,0,0,0)',
					border: '1px solid white',
					boxShadow: 'none',
					zIndex: 2,
					cursor: 'pointer',
					backdropFilter: 'blur(5px)',
					color: 'white',
				}}
			>
				◀
			</button>
			<button
				onClick={handleNext}
				style={{
					position: 'absolute',
					top: '50%',
					right: '10px',
					transform: 'translateY(-50%)',
					padding: '10px',
					backgroundColor: 'rgba(0,0,0,0.05)',
					border: '1px solid white',
					boxShadow: 'none',
					zIndex: 2,
					cursor: 'pointer',
					backdropFilter: 'blur(5px)',
					color: 'white',
				}}
			>
				▶
			</button>

			<button
				onClick={toggleFullScreen}
				style={{
					position: 'absolute',
					bottom: '60px',
					right: '20px',
					padding: '10px 15px',
					fontSize: '16px',
					zIndex: 2,
					cursor: 'pointer',
					backgroundColor: 'rgba(0,0,0,0.05)',
					border: '1px solid white',
					color: 'white',
					backdropFilter: 'blur(5px)',
					boxShadow: 'none',
				}}
			>
				{isFullscreen ? 'Exit Fullscreen' : 'Fullscreen'}
			</button>

			<div
				style={{
					position: 'absolute',
					bottom: '20px',
					left: '50%',
					transform: 'translateX(-50%)',
					display: 'flex',
					gap: '10px',
					zIndex: 2,
				}}
			>
				{activeList.map((_, idx) => (
					<span
						key={idx}
						onClick={() => startTransition(idx)}
						style={{
							width: '12px',
							height: '12px',
							borderRadius: '50%',
							backgroundColor: currentIndex === idx ? 'white' : 'gray',
							opacity: fade ? 1 : 0.3,
							transition: 'background-color 0.5s ease, opacity 0.5s ease',
							cursor: 'pointer',
						}}
					/>
				))}
			</div>
		</div>
	);
};

export default MediaSlider;
